    constraints: '### 提示\n\n本题 I/O 量较大，请使用快速的读入方式。\n```cpp\n#include<bits/stdc++.h>\nusing namespace std;\nint cid,test;\nnamespace FastIO {\n    char buf[1<<21], *p1=buf, *p2=buf;\n    inline int getch (void) {\n        return p1==p2&&(p2=(p1=buf)+fread(buf,1,1<<21,stdin),p1==p2)?EOF:*p1++;\n    }\n    inline int read (void) {\n        int x = 0, f = 1, ch = getch();\n        while(!isdigit(ch)) {\n            if(ch == \'-\') f = -f;\n            ch = getch();\n        }\n        while(isdigit(ch)) {\n            x = x * 10 + ch - \'0\';\n            ch = getch();\n        }\n        return x * f;\n    }\n    char buf2[1<<21], buf3[25];\n    int tp_l, buf2_l=-1;\n    inline void flush (void) {\n        fwrite (buf2, 1, buf2_l+1, stdout), buf2_l=-1;\n    }\n    inline void print (long long x, char ch=10) {\n        if(buf2_l>(1<<20)) flush();\n        if(x<0) buf2[++buf2_l]=\'-\', x=-x;\n        do buf3[++tp_l]=x%10+48;\n        while(x/=10);\n        do buf2[++buf2_l]=buf3[tp_l];\n        while(--tp_l);\n        buf2[++buf2_l] = ch;\n    }\n}\nusing FastIO::read;\nusing FastIO::print;\nint main(){\n	cid=read();test=read();\n	while(test--){\n		\n        //print(ans);\n	}\n	FastIO::flush();\n	return 0;\n}\n```\n\n\n### 样例解释\n\n对于第一组测试数据，可以将 $A_1,A_2,A_3$ 全部染成红色，得分为 $|2 - 1| + |1 - 2| = 2$，可以证明这是得分的最大值。\n\n对于第二组测试数据，可以将 $A_1,A_4$ 染成红色，$A_2,A_3$ 染成蓝色，得分为 $|4 - 1| + |3 - 2| = 4$，可以证明这是得分的最大值。\n\n对于第三组测试数据，可以将 $A_1,A_2,A_3,A_4,A_5,A_6,A_7,A_8$ 全部染成红色，得分为 $|5 - 3| + |2 - 5| + |5 - 2| + |1 - 5| + |2 - 1| + |1 - 2| + |4 - 1| = 17$，可以证明这是得分的最大值。\n\n### 数据规模与约定\n\n对于所有数据，保证：\n\n- $1 \\le t \\le 5$；\n- $1 \\le n \\le \\red{10^{7}}$；\n- $1 \\le A_i \\le 10^9$。\n\n::cute-table{tuack}\n| 测试点编号 | $n \\le$ | $A_i \\le$ |\n|:-:|:-:|:-:|\n| $1 \\sim 4$ | $20$ | $20$ |\n| $5 \\sim 8$ | $2000$ | $2000$ |\n| $9,10$ | $10^7$ | $5$ |\n| $11 \\sim 13$ | $10^5$ | $10^9$ |\n| $14$ | $10^6$ | ^ |\n| $15$ | $2 \\times 10^6$ | ^ |\n| $16$ | $3 \\times 10^6$ | ^ |\n| $17$ | $4 \\times 10^6$ | ^ |\n| $18$ | $5 \\times 10^6$ | ^ |\n| $19,20$ | $10^7$ | ^ |\n\n\n时间限制：1500ms\n内存限制：512MB',
